@tailwind base;
@tailwind components;
@tailwind utilities;

[x-cloak] {
    display: none !important;
}

@layer components {
    /* Content cards, tables, wizard panel and modals. Opaque enough for long forms. */
    .glass-panel {
        @apply border border-white/30 bg-white/75 shadow-sm backdrop-blur-md dark:border-white/10 dark:bg-slate-900/65;
    }

    /* Top navigation and page heading bars. */
    .glass-bar {
        @apply border-b border-white/20 bg-white/70 backdrop-blur-md dark:bg-slate-900/60;
    }

    /* Login, register and other guest pages. */
    .glass-card {
        @apply rounded-2xl border border-white/30 bg-white/60 shadow-2xl backdrop-blur-lg dark:border-white/10 dark:bg-slate-900/50;
    }

    /* Inputs, selects and textareas sitting on glass. */
    .glass-input {
        @apply border-gray-300 bg-white/70 text-gray-900 placeholder-gray-500 dark:border-white/10 dark:bg-slate-800/60 dark:text-gray-100 dark:placeholder-gray-400;
    }

    /* Without backdrop-filter the blur is lost, so use near-solid colors to keep text readable. */
    @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
        .glass-panel,
        .glass-bar,
        .glass-card {
            @apply bg-white/95 dark:bg-slate-900/95;
        }

        .glass-input {
            @apply bg-white dark:bg-slate-800;
        }
    }
}

/* Responsive logo sizing — edit the width values here to resize every logo app-wide.
   The image keeps its aspect ratio automatically (height: auto). */
@layer components {
    .logo-responsive {
        width: auto;   /* 40px — mobile */
        height: 100px;
        max-width: 100%;
        object-fit: contain;
    }

    @media (min-width: 640px) {   /* sm */
        .logo-responsive {
            width: 3rem;  /* 48px */
        }
    }

    @media (min-width: 768px) {   /* md */
        .logo-responsive {
            width: 3.5rem; /* 56px */
        }
    }

    @media (min-width: 1024px) {  /* lg */
        .logo-responsive {
            width: 4rem;  /* 64px */
        }
    }
}
